<?php
namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
class Guest extends Model { use HasFactory, SoftDeletes; protected $guarded=[]; protected function casts():array{return ['date_of_birth'=>'date','preferences'=>'array'];} public function getFullNameAttribute():string{return trim($this->first_name.' '.$this->last_name);} public function reservations(){return $this->hasMany(Reservation::class);} public function loyaltyAccount(){return $this->hasOne(LoyaltyAccount::class);} public function crmPreferences(){return $this->hasMany(GuestPreference::class);} public function crmNotes(){return $this->hasMany(GuestNote::class);} public function tags(){return $this->belongsToMany(GuestTag::class);} public function feedback(){return $this->hasMany(GuestFeedback::class);} public function complaints(){return $this->hasMany(GuestComplaint::class);} public function marketingConsents(){return $this->hasMany(MarketingConsent::class);} }
